// Master Verified Dataset for Lo Sdrogo Golfometro (Synchronized with Official PDF)

export interface PlayerScorecard {
  name: string;
  position: number;
  totalScore: number;
  diffPar: number;
  holes: (number | null)[];
  holeCount: number;
  hios: number;
  disasters: number;
  capped: number;
  bestHole: number | null;
  worstHole: number | null;
}

export interface GolfatinaMatch {
  id: number;
  date: string;
  title: string;
  url: string;
  youtubeId: string;
  channel: string;
  totalPar: number;
  winner: string;
  winningScore: number;
  winningDiffPar: number;
  mvp: string;
  asino: string;
  totalHIOs: number;
  maxHoleScore: number;
  sdrogoCommentary: string;
  players: PlayerScorecard[];
  hasScorecard?: boolean;
}

export interface PlayerProfile {
  name: string;
  nickname: string;
  badge: string;
  color: string;
  accent: string;
  avatar: string;
  quote: string;
  bio: string;
  radar: {
    precisione: number;
    clutch: number;
    sdroganza: number;
    tiltControl: number;
    fortuna: number;
  };
  matchesPlayed: number;
  wins: number;
  winRate: number;
  podiums: number;
  podiumRate: number;
  avgScore: number;
  avgDiffPar: number;
  bestScore: number;
  worstScore: number;
  bestDiffPar: number;
  worstDiffPar: number;
  totalHoles: number;
  totalHIOs: number;
  hioRate: number;
  totalTwos: number;
  totalThrees: number;
  totalDisasters: number;
  totalCapped: number;
  nemesis: string;
  aliases?: string[];
  iconicMemes?: string[];
}

export interface H2HRecord {
  sharedMatches: number;
  p1Wins: number;
  p2Wins: number;
  draws: number;
  p1AvgScore: number;
  p2AvgScore: number;
  sharedMatchIds: number[];
}

export interface GlobalSummary {
  totalMatches: number;
  totalVideos: number;
  totalScorecards: number;
  totalHolesPlayed: number;
  totalHIOs: number;
  totalDisasters: number;
  mostWinsPlayer: string;
  bestDiffParRecord: number;
  worstScoreRecord: number;
}

